import icontract
from typing import Tuple


@icontract.require(lambda x: x >= 0)
@icontract.require(lambda y: y >= 0)
@icontract.ensure(lambda x, y, result: y != 0 or (result[0] == x and result[1] == 0))
@icontract.ensure(lambda x, y, result: y == 0 or (
    result[1] * y + result[0] == x and 0 <= result[0] < y and 0 <= result[1]))
def DivisionFunction(x: int, y: int) -> Tuple[int, int]:
    if y == 0:
        return (x, 0)
    r, q = x, 0
    while y <= r:
        r -= y
        q += 1
    return (r, q)
